CREATE OR REPLACE FUNCTION pct_to_numeric(pct_str TEXT)
RETURNS NUMERIC AS $$
BEGIN
    -- Return NULL if input is NULL
    IF pct_str IS NULL THEN
        RETURN NULL;
    END IF;

    -- Remove the '%' sign if present
    IF pct_str LIKE '%%' THEN
        -- Strip the '%' and convert to numeric, then divide by 100
        RETURN CAST(REPLACE(pct_str, '%', '') AS NUMERIC) / 100;
    ELSE
        -- No '%' sign found, return NULL
        RETURN NULL;
    END IF;
END;
$$ LANGUAGE plpgsql;
